mapper.select:
select d.`park_org_id`, r.`id`, r.`device_id`, r.`device_name`, r.`warn_type`, r.`warn_time`, r.canceled, r.`real_reason_type`, r.`opinion`, r.`status` from dev_device_info d right join dev_fire_warning_record r on d.device_id = r.device_id
d.deleted=0 and r.deleted=0 and r.device_type=#{q.deviceType}
and d.park_org_id=#{q.parkOrgId}
and r.device_name like concat('%',#{q.deviceName},'%')
and r.device_id like concat('%',#{q.deviceId},'%')
and r.warn_type=#{q.warnType}
and r.warn_time >= #{q.warnTimeStart} and r.warn_time <= #{q.warnTimeEnd}
and r.id in
#{recordId}
and d.park_org_id in
#{parkOrgId}
order by r.`warn_time` desc

select count(*)
from dev_device_info d
inner join dev_fire_warning_record r on d.device_id = r.device_id

    and d.deleted=0
    and d.park_org_id=#{parkOrgId}

        and r.warn_time >= #{startTime}


        and r.warn_time <= #{endTime}


        and r.status=#{status}
